import{_ as o,o as c,c as d,a1 as t}from"./chunks/framework.BKrM4vFX.js";const k=JSON.parse('{"title":"packages/core — ядро mock-services","description":"packages/core — ядро mock-services. © 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0 Инфраструктура, общая для адаптеров провайдеров. Протоколов здесь нет: подписи, машины состояний, форматы полей и тесто","frontmatter":{"sourcePath":"packages/core/README.md"},"headers":[{"level":1,"title":"packages/core — ядро mock-services","slug":"packagescore-ядро-mock-services","link":"#packagescore-ядро-mock-services","children":[{"level":2,"title":"API","slug":"api","link":"#api","children":[]},{"level":2,"title":"Песочницы (RFC-001): источники owner-token","slug":"Песочницы-rfc-001-источники-owner-token","link":"#Песочницы-rfc-001-источники-owner-token","children":[]},{"level":2,"title":"Байтовые квоты песочниц (PD-02, #74)","slug":"Байтовые-квоты-песочниц-pd-02-74","link":"#Байтовые-квоты-песочниц-pd-02-74","children":[]},{"level":2,"title":"Как добавить нового провайдера (спека §2)","slug":"Как-добавить-нового-провайдера-спека-§2","link":"#Как-добавить-нового-провайдера-спека-§2","children":[]}]}],"relativePath":"packages/core/README.md","filePath":"packages/core/README.md"}'),a={name:"packages/core/README.md"};function r(s,e,l,i,n,p){return c(),d("div",null,[...e[0]||(e[0]=[t('<p>© 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0</p><h1 id="packagescore-ядро-mock-services" tabindex="-1">packages/core — ядро mock-services <a class="header-anchor" href="#packagescore-ядро-mock-services" aria-label="Permalink to &quot;packages/core — ядро mock-services&quot;">​</a></h1><p>Инфраструктура, общая для адаптеров провайдеров. Протоколов здесь нет: подписи, машины состояний, форматы полей и тестовые карты — в <code>services/*</code>.</p><p>Zero dependencies, Node &gt;= 18. Self-test: <code>npm run test:core</code>.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><ul><li><p><code>createStore({stateFile, log})</code> → <code>{state, persist, restore}</code> — состояние сервиса с опциональной персистентацией (<code>MOCK_STATE_FILE</code>).</p><p><strong>Важно:</strong> <code>restore()</code> сливает файл в состояние «на месте» (<code>mergeInto</code>) и <strong>сохраняет идентичность вложенных объектов</strong>. Подсистемы захватывают ссылки на <code>state.notifications</code>/<code>state.callbacks</code> при старте; подмена объекта приводила к тому, что после рестарта очередь вебхуков смотрела в пустой объект и молча теряла недоставленные уведомления (дефект A-2 аудита 2026-10-08).</p></li><li><p><code>installGracefulShutdown({server, flush, log, signals, timeoutMs, exit})</code> — общий обработчик SIGTERM/SIGINT для адаптеров (MS-04): синхронный <code>flush()</code> отложенных записей → <code>server.close()</code> → <code>closeAllConnections()</code> → <code>exit(0)</code>; страховочный таймер <code>timeoutMs</code> (по умолчанию 1 с, unref), повторный сигнал идемпотентен. Возвращает функцию <code>shutdown(signal)</code> с <code>dispose()</code> (снятие обработчиков — для selftest&#39;ов). Сервисы зовут хелпер в <code>require.main === module</code>-блоке, передавая <code>flush: () =&gt; sandboxRuntime.flush()</code>.</p></li><li><p><code>createLog(tag)</code> — журналирование с таймстампом.</p></li><li><p><code>readBody(req, maxBytes)</code> / <code>parseBody(raw, contentType)</code> — входящие тела (JSON и form-urlencoded).</p></li><li><p><code>send(res, code, body, headers)</code> / <code>sendJson(res, payload, code, headers)</code> / <code>html(res, body, code)</code> — ответы.</p></li><li><p><code>escapeHtml(value)</code> — экранирование значений, пришедших от интегратора, на HTML-страницах сервисов (чек покупателю, <code>/admin</code>).</p></li><li><p><code>redactSecrets(value)</code> / <code>redactSecretsInText(text)</code> / <code>redactRawBody(raw)</code> / <code>summarizeBody(body, {maxKeys, maxValueLength})</code> — редакция секретов перед журналированием и логированием (F-09): ключи-секреты (<code>Authorization</code>, <code>Cookie</code>, <code>token</code>, <code>pass</code>/<code>password</code>, <code>CVV</code>, <code>CardData</code>, <code>PAN</code>, <code>signature</code>) заменяются на <code>[REDACTED]</code>, PII (ИНН, телефон, e-mail, ФИО) маскируются частично, а любая строка дополнительно сканируется на PAN (<code>looksLikePan</code>/<code>maskPan</code>: 13–19 цифр, префикс платёжной системы, контрольная сумма Luhn) и на <code>Basic</code>/<code>Bearer</code>-токены.</p></li><li><p><code>classifyKey(key)</code> → <code>&#39;secret&#39; | &#39;pii&#39; | &#39;safe&#39;</code> — класс поля по имени; <code>maskPiiValue(key, value)</code> — частичная маска PII.</p></li><li><p><code>createJournal({size, baseUrl, maxEntryChars, sandboxScope})</code> → <code>{record, list, clear, clearFor, dropScope}</code> — журнал входящих запросов для <code>/admin/journal</code>: метод, путь, ключевые поля, код ответа, длительность. Запись редактируется до сохранения (F-09): заголовки — через allowlist (<code>Content-Type</code>, <code>Content-Length</code>, <code>User-Agent</code>, <code>X-Mock-*</code>), тело и сырой payload — через <code>redactSecrets</code>/<code>redactRawBody</code>, длина полей и всей записи ограничена. С <code>sandboxScope</code> (адаптеры передают <code>() =&gt; sandboxRuntime.current()</code>) записи живут в разделе записи текущей песочницы (PB-13, #52); без него — прежний одиночный журнал.</p></li><li><p><code>createScenarioRegistry({clock, size, maxRules, maxRuleBytes, sandboxScope})</code> — реестр сценариев <code>X-Mock-Scenario</code> и правил <code>POST /mock/scenarios</code> с историей срабатываний. С <code>sandboxScope</code> правила и история изолированы по записи песочницы (PA-51/PG-04, #52); дефолтные лимиты — 200 правил на песочницу и 8 KiB на правило (UTF-8 байты сериализованного JSON), превышение бросает ошибку с <code>code</code> <code>rule_cap_exceeded</code>/<code>rule_too_large</code> до мутации. Повторная запись с тем же <code>id</code> — update на месте. <code>clearRulesFor</code>/<code>clearHistoryFor</code>/ <code>dropScope</code> оперируют разделом конкретной записи песочницы.</p></li><li><p><code>postJson(url, payload, timeoutMs, options)</code> — исходящий POST/GET (http/https по схеме; другие схемы отклоняются, редиректы не отслеживаются; для IPv6-литералов скобки <code>[...]</code> нормализуются перед подключением и сохраняются в заголовке <code>Host</code> — PA-25).</p></li><li><p><code>flagEnabled(value, fallback)</code> — разбор boolean-настроек из env: <code>1</code>/<code>true</code>/<code>yes</code>/<code>on</code> против <code>0</code>/<code>false</code>/<code>no</code>/<code>off</code>, пустое значение — <code>fallback</code> (F-08: <code>=1</code> больше не «молчит»).</p></li><li><p><code>defaultBlockPrivateHosts(env)</code> — дефолт SSRF-политики ядра, согласованный с адаптерами (PA-58): <code>flagEnabled(MOCK_BLOCK_PRIVATE_WEBHOOKS, flagEnabled(MOCK_HOSTED, false))</code>.</p></li><li><p><code>isPrivateAddress(ip)</code> / <code>isPrivateHost(url)</code> — классификация IP-литералов и URL («приватный/служебный адрес», включая <code>ff00::/8</code>, TEST-NET-1/2/3, <code>2001:db8::/32</code> и <code>64:ff9b:1::/48</code> — PA-26) для защиты вебхуков от SSRF.</p></li><li><p><code>resolvePublicHost(url, {lookup})</code> / <code>assertPublicHost(url, {lookup})</code> — async-проверка перед исходящим запросом: схема http/https, публичный IP, имя резолвится один раз только в публичные адреса и пиннится к сокету (защита от DNS TOCTOU / rebinding — §7.3, PG-11); бросает <code>Error</code> с <code>code === &#39;SSRF_BLOCKED&#39;</code>.</p></li><li><p><code>checkControlAccess(req, {adminToken, operatorToken, surface, hosted})</code> — единый access-control управляющей поверхности (F-07): роли <code>admin</code>/<code>operator</code>, constant-time сравнение токена, fail-closed при <code>hosted</code> без секрета.</p></li><li><p><code>createDeliveryQueue({...})</code> — очередь исходящих вебхуков с ретраями: запись живёт в состоянии сервиса (переживает рестарт), <code>retryMs</code>/<code>maxAttempts</code> настраиваются, критерий доставки — хук (<code>isOk</code>: у Т-Банка это 200 + тело «OK», у Ferma — любой 2xx). Тик — раз в секунду; <code>awaitSequential</code> — доставлять по одной (Т-Банк) или пачкой (Ferma). Дефолт <code>blockPrivateHosts</code> — <code>defaultBlockPrivateHosts()</code> (локально <code>false</code>, при <code>MOCK_HOSTED=1</code> — <code>true</code>, PA-58); то же правило действует в <code>verifyMerchantWebhook({...})</code>.</p><p>Гарантии очереди (закреплены тестами):</p><ol><li>запись, находящаяся «в полёте», не отправляется повторно — ретраи идут строго по расписанию, даже если вебхук отвечает медленнее, чем тик (дефект A-3: без защиты одна нотификация уходила параллельными POST-ами);</li><li>терминальный статус — флаг <code>entry.done</code> (а не <code>nextAttemptAt = Infinity</code>, который сериализовался в <code>null</code> и после рестарта считался «пора слать снова», дефект A-4);</li><li><code>request(entry)</code>, бросивший исключение, не роняет тик — запись уходит в <code>onFailure</code> с текстом ошибки;</li><li>при <code>blockPrivateHosts: true</code> (или по умолчанию в <code>MOCK_HOSTED=1</code>) отправка на приватные/служебные адреса и имена, которые в них резолвятся, блокируется с привязкой проверенного IP к соединению против DNS TOCTOU (дефекты A-18/F-08, #51 PF-01/PA-25/PA-26/PA-58/PG-11);</li><li><code>awaitSequential: true</code> — записи уходят строго по одной и в порядке очереди: следующая запись не стартует, пока предыдущая не завершилась, и новый тик не начинается поверх идущего (F-29: даже медленный приёмник не может получить статусы одного платежа не по порядку).</li></ol></li><li><p><code>createErrorCatalog({provider, docsBase, codes})</code> — каталог ошибок DX-слоя: <code>{код, объяснение, поле, подсказка, ссылка на официальный раздел доки}</code>.</p></li></ul><h2 id="Песочницы-rfc-001-источники-owner-token" tabindex="-1">Песочницы (RFC-001): источники owner-token <a class="header-anchor" href="#Песочницы-rfc-001-источники-owner-token" aria-label="Permalink to &quot;Песочницы (RFC-001): источники owner-token&quot;">​</a></h2><p><code>createSandboxRuntime({mode, ...})</code> даёт адаптеру <code>admit</code>, <code>run</code>, <code>selector</code>, <code>ownerTokenOf</code>, <code>isOperatorToken</code>, <code>isOperatorRequest</code>, <code>recordAuthorized</code>, <code>recordByOwnerToken</code> и операции жизненного цикла песочниц. В <code>owned</code>-режиме (включается <code>MOCK_HOSTED=1</code> или явным <code>MOCK_TENANCY=owned</code>) доступ к песочнице даёт только её owner-token: <strong>знание id доступа не даёт</strong> (F-12).</p><p><code>ownerTokenOf(req)</code> читает owner-token в строгом порядке (задача #98):</p><table tabindex="0"><thead><tr><th>#</th><th>Источник</th><th>Комментарий</th></tr></thead><tbody><tr><td>1</td><td><code>X-Sandbox-Token: &lt;токен&gt;</code></td><td>явный заголовок владельца — самый приоритетный</td></tr><tr><td>2</td><td><code>X-Owner-Token: &lt;токен&gt;</code></td><td>синоним; уступает <code>X-Sandbox-Token</code></td></tr><tr><td>3</td><td>cookie <code>mock_sandbox_token=&lt;токен&gt;</code></td><td>сессионная cookie консоли; читается с декодированием (Ф-2, #121)</td></tr><tr><td>4</td><td><code>Authorization: Bearer &lt;токен&gt;</code></td><td>fallback для клиентов, знающих только Bearer</td></tr><tr><td>5</td><td><code>?sandbox_token=&lt;токен&gt;</code></td><td>только non-hosted <code>namespaces</code> (WARN об устаревании); в <code>owned</code> и в hosted отклоняется fail-closed (Ф-3, #121)</td></tr></tbody></table><p>Порядок важен: у адаптеров, чей бизнес-контракт сам ходит по <code>Authorization: Bearer &lt;токен&gt;</code> (first-ofd — токен очереди, vtb — OAuth <code>access_token</code>), Bearer приоритетнее явного заголовка означал, что ядро принимало токен бизнес-авторизации за owner-token, владелец не находился и получал 401 «знание ID не является доступом». Bearer оставлен как fallback, а не убран: клиенты, передающие owner-token только в <code>Authorization</code>, продолжают работать.</p><p>Правила, закреплённые тестами <code>packages/core/selftest.js</code>:</p><ul><li>источник с пустым или пробельным значением считается <strong>отсутствующим</strong> и не затеняет следующие источники;</li><li>невалидный/чужой owner-token → <code>admit</code> отвечает <code>kind: &#39;unauthorized&#39;</code> (HTTP 401), состояние песочницы не выдаётся;</li><li>операторский путь (<code>MOCK_OPERATOR_TOKEN</code>) от этого порядка не зависит: <code>isOperatorRequest</code> дополнительно сверяет <code>tokenMatches</code> по самому <code>Authorization</code> / <code>X-Operator-Token</code> / query, поэтому оператор с Bearer узнаётся даже когда owner-заголовок занят чужим токеном;</li><li>при <code>mode</code> <code>namespaces</code>/<code>off</code> (self-hosted) owner-token не требуется вовсе, и бизнес-заголовки адаптера не трактуются как owner-token.</li></ul><p>Опция <code>hosted</code> (<code>MOCK_HOSTED=1</code>, MS-12, #121): при пустом <code>defaultOwnerToken</code> песочница <code>default</code> <strong>не обслуживается</strong> — бизнес- и form-маршруты без селектора получают <code>kind: &#39;not-found&#39;</code> (адаптеры отдают 404 с точной причиной и хинтом), публичная инфраструктура (<code>/health</code>, <code>/openapi.json</code>, <code>/sandboxes</code>) отдаётся detached public record, именованные песочницы работают по owner-token. Управляющая поверхность (<code>policy: &#39;control&#39;</code>) MS-12 не перекрывает: у неё свой fail-closed гейт MS-06. Без <code>MOCK_HOSTED</code> поведение <code>default</code> не меняется.</p><p>Диагностика <code>hosted</code>/self-hosted вынесена в <code>defaultSandboxStatus({ownerToken, hosted, tenancy})</code> → <code>default=owner-token | default=closed (MS-12: …) | default=open</code> — этой строкой адаптеры печатают статус при старте.</p><p>Сессионные cookie консоли (Ф-1, #121): <code>sessionCookieHeader(name, value)</code> (HttpOnly, <code>SameSite=Strict</code>, <code>Path=/</code>, <code>Max-Age</code>), <code>sessionCookiesFromQuery(req, {...})</code> (переносит принятые из query <code>admin_token</code>/<code>operator_token</code>/<code>sandbox_token</code> в cookie; в hosted возвращает пустой список) и <code>attachResponseCookies(res, cookies)</code> (добавляет <code>Set-Cookie</code>, не перетирая собственные cookie ответа). <code>readCookieValue(req, name)</code> — чтение cookie с декодированием (<code>%3D</code> → <code>=</code>, разделение по первому <code>=</code>).</p><h2 id="Байтовые-квоты-песочниц-pd-02-74" tabindex="-1">Байтовые квоты песочниц (PD-02, #74) <a class="header-anchor" href="#Байтовые-квоты-песочниц-pd-02-74" aria-label="Permalink to &quot;Байтовые квоты песочниц (PD-02, #74)&quot;">​</a></h2><p><code>createSandboxRuntime</code> принимает два независимых лимита (целые байты UTF-8 сериализованного JSON, не число документов):</p><table tabindex="0"><thead><tr><th>Опция / env всех 9 сервисов</th><th>По умолчанию</th><th>Значение <code>0</code></th></tr></thead><tbody><tr><td><code>maxStateBytes</code> / <code>MOCK_SANDBOX_MAX_STATE_BYTES</code></td><td>пусто / <code>null</code> / <code>undefined</code>: 8 МиБ (<code>8388608</code>), если <code>maxDocuments &gt; 0</code>, иначе без лимита</td><td>выключить per-sandbox квоту</td></tr><tr><td><code>globalMaxStateBytes</code> / <code>MOCK_SANDBOX_GLOBAL_MAX_STATE_BYTES</code></td><td>пусто / <code>null</code> / <code>undefined</code>: 64 МиБ (<code>67108864</code>), независимо от <code>maxDocuments</code> и tenancy</td><td>выключить глобальный бюджет</td></tr></tbody></table><p>Env задавайте целыми байтами, например <code>MOCK_SANDBOX_MAX_STATE_BYTES=4194304</code>. Адаптеры используют существующий <code>parseMsOr</code>: пустое/невалидное значение оставляет дефолт, явный <code>0</code> выключает соответствующий лимит. <code>refreshStateQuota()</code> обновляет снимки отката и кэш размеров после startup-restore и миграций адаптера (не вызывать после бизнес-мутации). <code>stats()</code> возвращает эффективные <code>maxStateBytes</code> и <code>globalMaxStateBytes</code>.</p><p>Глобальный бюджет — сумма состояний <strong>всех записей одного рантайма</strong>, включая <code>default</code>, а не бюджет всего compose-стенда. Размер соседей кэшируется по версии: запись не сериализует весь реестр. Удаление/TTL освобождает бюджет, reset и замена снимка учитывают новый размер вместо старого (без двойного учёта). Создание учитывает начальное состояние песочницы; отказ не оставляет запись.</p><p>Проверки выполняются при <code>checkDocuments()</code> (до бизнес-записи), <code>persist()</code> (глобальный бюджет после мутации) и <code>importState()</code> (оба байтовых лимита после слияния). Существующая семантика per-sandbox бизнес-квоты сохранена: проверка до записи, а импорт проверяется строго после слияния. Ровно лимит разрешён при импорте/сохранении; следующая предварительная проверка откажет. Превышение глобального бюджета или байтового лимита импорта возвращает HTTP <strong>400</strong>, <code>errorCode: 400</code>, <code>kind: &#39;bytes&#39;</code>, <code>used</code>, <code>limit</code>, <code>sandbox</code> и <code>code: &#39;sandbox_state_budget_exceeded&#39;</code> / <code>&#39;sandbox_state_quota_exceeded&#39;</code>. В ядре это исключения <code>SANDBOX_STATE_BUDGET_EXCEEDED</code> / <code>SANDBOX_QUOTA_BYTES</code>; адаптеры отображают их через <code>sendSandboxStateQuotaError(res, error)</code>. Отклонённое состояние восстанавливается на месте из последнего принятого JSON, не пишется на диск, соседние песочницы не меняются.</p><p><strong>Квота per-sandbox ≠ память контейнера.</strong> 64 МиБ ограничивают накопление JSON-состояния (~8 заполненных по 8 МиБ песочниц), оставляя часть <code>mem_limit: 128m</code> под процесс. Это не гарантия RSS: JS-объекты, снимки отката, временные строки, правила/история/журнал и очереди исполнения имеют дополнительные расходы. Дочернее состояние остаётся volatile и в байтовый бюджет не входит. Восстановление существующих файлов при старте не отбрасывает данные ради квоты; после восстановления превышение блокирует следующие записи, пока оператор не уменьшит состояние, не сбросит/удалит песочницы или не поднимет бюджет. Для жёсткой защиты памяти сохраняйте контейнерный лимит и подбирайте бюджет по измеренному RSS конкретного адаптера; <code>0</code> годится только для доверенного стенда.</p><h2 id="Как-добавить-нового-провайдера-спека-§2" tabindex="-1">Как добавить нового провайдера (спека §2) <a class="header-anchor" href="#Как-добавить-нового-провайдера-спека-§2" aria-label="Permalink to &quot;Как добавить нового провайдера (спека §2)&quot;">​</a></h2><ol><li>Новый каталог в <code>services/&lt;provider&gt;-mock</code> с <code>server.js</code> на ядре.</li><li>В адаптере — только декларация протокола: маршруты, схемы, коды ошибок, машина состояний, тестовые реквизиты. Ошибки — через <code>createErrorCatalog</code> (код + поле + подсказка + ссылка на официальную доку).</li><li>Журнал входящих запросов — <code>createJournal</code> + <code>GET /admin/journal</code>.</li><li>HTML-страницы (админка, чеки) — только через <code>escapeHtml</code>.</li><li>Selftest по образцу существующих: поднять сервер на эфемерном порту, прогнать все сценарии контракта end-to-end, включая негативные и «рестарт с <code>MOCK_STATE_FILE</code>». Флаки-тесты (<code>sleep</code>-ожидания, фиксированные порты) не принимаются — см. <code>CONTRIBUTING.md</code>.</li></ol>',26)])])}const _=o(a,[["render",r]]);export{k as __pageData,_ as default};
